'use strict';
const $=id=>document.getElementById(id);
const el=(tag,text)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;return node;};
let common=null,busy=false,edited=false;

function status(message,error=false){$('common-status').textContent=message;$('common-status').classList.toggle('error',error);$('common-status').setAttribute('role',error?'alert':'status');}
function key(){const value=$('common-key').value.trim();if(!/^[A-Za-z0-9._-]{20,512}$/.test(value))throw Error('본인의 Gemini API 키를 입력해 주세요.');return value;}
async function api(path,payload,method){const response=await fetch('/api/'+path,{method:method||(payload===undefined?'GET':'POST'),credentials:'same-origin',headers:payload===undefined?{}:{'Content-Type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload)});if(!response.ok){let detail;try{const value=await response.json();detail=value.message||value.detail?.message||value.error||value.detail;}catch{}throw Error(typeof detail==='string'?detail:'요청을 처리하지 못했습니다.');}return response.json();}
async function fileData(file){return {name:file.name,base64:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);})};}
function ready(){return !!common&&common.intake.files.every(file=>file.status!=='deferred')&&common.intake.sources.every(source=>!source.requires_verification||common.intake.confirmations.some(receipt=>receipt.source_id===source.source_id));}
function gates(){const has=!!common;const draft=common?.result?.draft;const checked=common?.status==='ready'&&!common?.result?.review?.blocking;$('common-generate').disabled=busy||!has||!ready();$('common-ocr').disabled=busy||!has;$('common-confirm').disabled=busy||!has;$('common-delete').disabled=busy||!has;$('common-recheck').disabled=busy||!draft||!edited;$('common-answer').disabled=busy||!has;$('common-export').disabled=busy||!checked||edited||!$('common-final-confirm').checked;}
async function act(task){if(busy)return;busy=true;gates();status('처리 중입니다. 잠시 기다려 주세요.');try{await task();}catch(error){status(error.message,true);}finally{busy=false;gates();}}
function appendFileStatus(data){const host=$('common-files');host.replaceChildren();for(const file of data.intake.files)host.append(el('p',file.filename+' · '+file.status+(file.reason?' · '+file.reason:'')));}
function renderSources(data){appendFileStatus(data);$('common-ocr').hidden=!data.intake.files.some(file=>file.status==='deferred');const transcription=$('common-transcriptions');transcription.replaceChildren();for(const file of data.intake.files){if(!file.manual_transcription_available)continue;for(const page of file.transcription_pages||[1]){const label=el('label',file.filename+' · '+page+'쪽 원문 직접 전사');const input=el('textarea');input.rows=5;input.dataset.sha=file.document_sha256;input.dataset.page=page;input.placeholder='이미지 또는 스캔 PDF의 해당 페이지 전체 원문을 직접 확인해 입력';label.append(input);transcription.append(label);}}$('common-transcription-save').hidden=!transcription.childElementCount;
 const confirmations=$('common-confirmations');confirmations.replaceChildren();const accepted=new Set(data.intake.confirmations.map(item=>item.source_id));for(const source of data.intake.sources){if(!source.requires_verification||accepted.has(source.source_id))continue;const details=el('details');const summary=el('summary',source.filename+' · '+(source.location||'원문')+' · 대조 필요');const quote=el('blockquote',source.text);const label=el('label','원본과 이 전체 원문을 대조함');label.className='check';const input=el('input');input.type='checkbox';input.dataset.receipt=source.source_id;input.dataset.fingerprint=source.verification_fingerprint;label.prepend(input);details.append(summary,quote,label);confirmations.append(details);}$('common-confirm').hidden=!confirmations.childElementCount;}
function renderQuestions(data){const panel=$('common-questions'),holder=$('common-question-fields');holder.replaceChildren();const questions=data.result?.questions||[];panel.hidden=!questions.length;for(const question of questions.slice(0,2)){const label=el('label',question);const input=el('textarea');input.rows=2;input.dataset.question=question;label.append(input);holder.append(label);}}
function renderEvidence(data){const holder=$('common-citations');holder.replaceChildren();for(const source of data.evidence||[]){const article=el('article');article.append(el('strong','['+source.source_id+'] '+source.filename+' · '+(source.location||source.page||source.sheet||'원문')));article.append(el('blockquote',source.text));article.append(el('small','원본 SHA-256 '+(source.document_sha256||'기록 없음')));holder.append(article);}}
function renderResult(data){const result=data.result,holder=$('common-result'),review=$('common-review');holder.hidden=!result?.draft;if(!result?.draft)return;edited=false;$('common-final-confirm').checked=false;$('common-title').value=result.draft['제목']||'';$('common-summary').value=result.draft['요약']||'';$('common-body').value=result.draft['본문']||'';review.replaceChildren();const blocked=result.review?.blocking||data.status!=='ready';review.classList.toggle('error',blocked);review.append(el('strong',blocked?'검수 확인이 더 필요합니다.':'출처·수치·누락 검수 통과'));for(const item of result.review?.warnings||[]){review.append(el('p',(item.field?item.field+' · ':'')+(item.message||item.code||'검수 항목')));}renderEvidence(data);}
function render(data){common=data;$('common-evidence').hidden=false;$('common-writing').hidden=false;renderSources(data);renderQuestions(data);renderResult(data);gates();if(data.status==='failed')status(data.error?.message||'작업을 완료하지 못했습니다.',true);else if(data.status==='needs_information')status('부족한 정보를 확인해 주세요. 최대 두 질문만 표시합니다.');else if(data.status==='needs_revision')status('초안은 작성됐으나 검수 항목을 해결해야 다운로드할 수 있습니다.');else if(data.status==='ready')status('초안과 검수를 완료했습니다. 내용을 확인한 뒤 다운로드하세요.');else if(data.status==='processing')status('AI가 문서를 작성·검수 중입니다.');else status('자료를 등록했습니다. 원문 상태를 확인한 뒤 초안을 작성하세요.');}
async function settle(data){render(data);while(common.status==='processing'){await new Promise(resolve=>setTimeout(resolve,2500));render(await api('common/jobs/'+common.job_id));}}
function forget(){common=null;edited=false;sessionStorage.removeItem('commonJobId');$('common-evidence').hidden=true;$('common-writing').hidden=true;$('common-result').hidden=true;$('common-questions').hidden=true;$('common-final-confirm').checked=false;gates();status('입력이 바뀌었습니다. 자료를 다시 등록하면 새 문서 작업을 시작합니다.');}

$('common-upload').onclick=()=>act(async()=>{const form=document.querySelector('input[name="common-form"]:checked')?.value;const instruction=$('common-instruction').value.trim(),notes=$('common-notes').value.trim();const files=[...$('common-sources').files],template=$('common-template').files[0];if(!instruction||(!notes&&!files.length))throw Error('작성 지시와 자료 파일 또는 사실 메모를 입력해 주세요.');if(files.length>12||files.length+(notes?1:0)>12)throw Error('원자료는 메모를 포함해 최대 12개입니다.');if(files.reduce((sum,file)=>sum+file.size,template?.size||0)>12*1024*1024)throw Error('한 번의 업로드는 12 MB 이하이어야 합니다.');const payload={form_type:form,instruction,notes,sources:await Promise.all(files.map(fileData)),template:template?await fileData(template):undefined};render(await api('common/jobs',payload));sessionStorage.setItem('commonJobId',common.job_id);});
$('common-delete').onclick=()=>act(async()=>{if(!common)return;await api('common/jobs/'+common.job_id,{},'DELETE');$('common-instruction').value='';$('common-notes').value='';$('common-sources').value='';$('common-template').value='';forget();status('현재 작업과 업로드 자료를 삭제했습니다.');});
$('common-ocr').onclick=()=>act(async()=>{if(!common)throw Error('먼저 자료를 등록해 주세요.');await api('jobs/'+common.job_id+'/intake',{auto_ocr:true,gemini_api_key:key()});await settle(await api('common/jobs/'+common.job_id));});
$('common-transcription-save').onclick=()=>act(async()=>{const transcriptions={};for(const input of document.querySelectorAll('[data-sha]')){if(!input.value.trim())throw Error('읽지 못한 모든 페이지의 원문을 입력해 주세요.');(transcriptions[input.dataset.sha]??=[]).push({page:Number(input.dataset.page),text:input.value});}await api('jobs/'+common.job_id+'/intake',{transcriptions});render(await api('common/jobs/'+common.job_id));});
$('common-confirm').onclick=()=>act(async()=>{const receipts=[...document.querySelectorAll('[data-receipt]')].filter(input=>input.checked).map(input=>({source_id:input.dataset.receipt,fingerprint:input.dataset.fingerprint}));if(!receipts.length)throw Error('원본과 대조한 원문을 선택해 주세요.');await api('jobs/'+common.job_id+'/intake',{receipts,confirmed:true});render(await api('common/jobs/'+common.job_id));});
$('common-generate').onclick=()=>act(async()=>{if(!ready())throw Error('미확인 원문을 확인해 주세요.');await settle(await api('common/jobs/'+common.job_id+'/generate',{gemini_api_key:key()}));});
$('common-answer').onclick=()=>act(async()=>{const answers={};for(const input of document.querySelectorAll('[data-question]')){if(input.value.trim())answers[input.dataset.question]=input.value.trim();}if(!Object.keys(answers).length)throw Error('답변을 입력해 주세요.');await settle(await api('common/jobs/'+common.job_id+'/generate',{answers,gemini_api_key:key()}));});
for(const id of ['common-title','common-summary','common-body'])$(id).addEventListener('input',()=>{if(common?.result){edited=true;$('common-final-confirm').checked=false;gates();status('내용이 바뀌었습니다. 수정본을 다시 검수해야 다운로드할 수 있습니다.');}});
$('common-recheck').onclick=()=>act(async()=>{const draft={'제목':$('common-title').value,'요약':$('common-summary').value,'본문':$('common-body').value};await settle(await api('common/jobs/'+common.job_id+'/review',{draft,gemini_api_key:key()}));});
$('common-final-confirm').onchange=gates;
$('common-export').onclick=()=>act(async()=>{if(!common||edited||common.status!=='ready'||!$('common-final-confirm').checked)throw Error('현재 초안과 출처를 확인해 주세요.');const response=await fetch('/api/common/jobs/'+common.job_id+'/export',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true})});if(!response.ok){let detail;try{detail=await response.json();}catch{}throw Error(detail?.message||detail?.detail?.message||'다운로드 검수를 통과하지 못했습니다.');}const blob=await response.blob(),link=el('a');link.href=URL.createObjectURL(blob);link.download=common.form_type+'_document_package.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);status('문서와 출처·검수 기록을 다운로드했습니다.');});
for(const id of ['common-instruction','common-notes','common-sources','common-template'])$(id).addEventListener('change',()=>{if(common)forget();});
document.querySelectorAll('input[name="common-form"]').forEach(input=>input.addEventListener('change',()=>{if(common)forget();}));
Promise.all([api('me'),api('health')]).then(async([identity])=>{$('access-status').textContent=identity.access_mode==='guest'?'초대된 담당자 · 가입 불필요':'보호된 개인 작업실';const identifier=sessionStorage.getItem('commonJobId');if(identifier&&/^[0-9a-f]{32}$/.test(identifier)){try{render(await api('common/jobs/'+identifier));return;}catch{sessionStorage.removeItem('commonJobId');}}status('연결 완료. 작성할 문서를 선택하고 지시와 자료를 입력해 주세요.');}).catch(error=>status(error.message,true));
addEventListener('pagehide',()=>{$('common-key').value='';});
gates();
